import {run,boot,text,work,sleep,assert,info,E,surfaceUrl} from './browser-lib.mjs';import fs from 'node:fs';
const results=[];for(const target of ['core.ask-surface','core.search-v3-surface']){
const r=await run('cold-replacement-'+target,async({p,wire,dir,snap})=>{
 const old='Old task on unrelated decoy';await boot(p,{query:old,docIds:[info.decoy]},'core.ask-surface');const first={url:p.url(),text:await p.getByTestId('sv3-composer-input').inputValue(),ui:await text(p)};await snap('first');
 const query='  Explain # & % 日本語\nexactly  ';const incomingUrl='http://127.0.0.1:'+info.port+'/'+surfaceUrl(target,{query,docIds:[info.chosen]});await p.goto(incomingUrl,{waitUntil:'domcontentloaded'});await p.getByTestId('sv3-composer-input').waitFor({timeout:60000});await sleep(1200);const value=await p.getByTestId('sv3-composer-input').inputValue();const ui=await text(p);await snap('second');const checks={text:value===query,noAutomaticModelWork:work(wire).length===0,chosen:ui.includes('chosen-alpha.txt')};const o={old,query,first,incomingUrl,finalUrl:p.url(),value,ui,checks,modelState:'fresh own Engine; chat not configured or activated'};fs.writeFileSync(dir+'/observations.json',JSON.stringify(o,null,2));assert.ok(Object.values(checks).every(Boolean),JSON.stringify(checks));
 const key='justsearch.draft.attachment.v1.search-v3.main';
 const recovered=await p.evaluate(k=>JSON.parse(sessionStorage.getItem(k)).payload,key);
 assert.equal(recovered.drafts.length,2);assert.ok(recovered.drafts.some(d=>d.text===old));
 await p.getByTestId('sv3-recovery-review-copy').click();await sleep(300);
 assert.equal(await p.getByTestId('sv3-composer-input').inputValue(),old);
 assert.ok(await p.getByTestId('sv3-draft-review').isVisible());assert.equal(work(wire).length,0);
 const swapped=await p.evaluate(k=>JSON.parse(sessionStorage.getItem(k)).payload,key);
 assert.ok(swapped.drafts.some(d=>d.text===query));await snap('review-previous');
 o.previousDraftReviewable=true;o.incomingStillRetained=true;o.preReviewRecovery=recovered;return o;
});results.push(r);if(r.status!=='pass')process.exitCode=1;}fs.writeFileSync(E+'/'+info.label+'/cold-summary.json',JSON.stringify(results,null,2));

