import {run,boot,text,work,sleep,assert,info,E,surfaceUrl} from './browser-lib.mjs';import fs from 'node:fs';
const results=[];
for(const target of ['core.ask-surface','core.search-v3-surface']){
const r=await run('cold-capacity-'+target,async({p,wire,snap})=>{
 await boot(p,{query:'retained A',docIds:[info.decoy]},'core.ask-surface');
 await p.evaluate(hash=>{window.location.hash=hash},surfaceUrl('core.ask-surface',{query:'current B',docIds:[info.chosen]}));await sleep(700);
 assert.equal(await p.getByTestId('sv3-composer-input').inputValue(),'current B');
 const query='  Incoming C # & % 日本語\nexactly  ';
 await p.goto('http://127.0.0.1:'+info.port+'/'+surfaceUrl(target,{query,docIds:[info.chosen]}),{waitUntil:'domcontentloaded'});
 await p.getByTestId('sv3-composer-input').waitFor({timeout:60000});await sleep(1200);
 const value=await p.getByTestId('sv3-composer-input').inputValue(),ui=await text(p),url=p.url();await snap('refused');
 const checks={oldComposer:value==='current B',incomingAddress:new URLSearchParams(new URL(url).hash.split('?')[1]).get('query')===query,realReason:ui.includes('Only two draft preparations can be retained'),noAutomaticWork:work(wire).length===0};
 assert.ok(Object.values(checks).every(Boolean),JSON.stringify(checks));return {checks,url,value,ui};
});results.push(r);if(r.status!=='pass')process.exitCode=1;
}fs.writeFileSync(E+'/'+info.label+'/capacity-summary.json',JSON.stringify(results,null,2));

