import os,sys,subprocess,tempfile,time,json,signal,shutil,urllib.request,urllib.error,hashlib,socket
from pathlib import Path
E=Path(__file__).parent;label=sys.argv[1];R=Path(sys.argv[2]).resolve();O=E/('runtime-'+label);O.mkdir(exist_ok=True);jobs=O/'jobs';jobs.mkdir(exist_ok=True)
P=Path(tempfile.mkdtemp(prefix='jsv-eng-',dir='/tmp'))
for d in ['home','data','index','corpus','config','cache','state','xdgdata','tmp']: (P/d).mkdir()
(P/'corpus/chosen-alpha.txt').write_text('Flip verifier paired corpus. Chosen alpha answer is ALPHA_CEDAR_731. Project codename Cedar.\n')
(P/'corpus/unchosen-decoy.txt').write_text('Flip verifier paired corpus. Unchosen decoy answer is DECOY_ZULU_942. Project codename Zulu.\n')
env={k:v for k,v in os.environ.items() if not k.startswith('JUSTSEARCH_') and k not in ['JAVA_OPTS','JAVA_TOOL_OPTIONS','_JAVA_OPTIONS','JDK_JAVA_OPTIONS','UI_OPTS','DISPLAY','WAYLAND_DISPLAY']}
env.update(CUDA_VISIBLE_DEVICES='-1',HOME=str(P/'home'),XDG_CONFIG_HOME=str(P/'config'),XDG_DATA_HOME=str(P/'xdgdata'),XDG_CACHE_HOME=str(P/'cache'),XDG_STATE_HOME=str(P/'state'),TMPDIR=str(P/'tmp'),UI_OPTS='-Duser.home='+str(P/'home'),JUSTSEARCH_HOME=str(P/'data'),JUSTSEARCH_DATA_DIR=str(P/'data'),JUSTSEARCH_INDEX_BASE_PATH=str(P/'index'),JUSTSEARCH_API_PORT='0',JUSTSEARCH_REPO_ROOT=str(R),JUSTSEARCH_AI_DISABLED='true',JUSTSEARCH_AI_EMBED_ENABLED='false',JUSTSEARCH_NER_ENABLED='false',JUSTSEARCH_SPLADE_ENABLED='false',JUSTSEARCH_BGE_M3_ENABLED='false',JUSTSEARCH_RERANK_ENABLED='false',JUSTSEARCH_RERANK_CHUNKS_ENABLED='false',JUSTSEARCH_POLICY_GPU_ACCELERATION_ENABLED='false',JUSTSEARCH_EXTRACTION_SANDBOX_MODE='in_process')
engine=None;vite=None;child=None;seen={}
def cohort():
 rows={}
 for p in Path('/proc').iterdir():
  if not p.name.isdecimal():continue
  try:
   f=p.joinpath('stat').read_text().rsplit(') ',1)[1].split();rows[int(p.name)]=(int(f[1]),f[19])
  except OSError:pass
 ids={p.pid for p in [engine,vite,child] if p and p.poll() is None}
 for _ in range(15):
  more={pid for pid,(ppid,_) in rows.items() if ppid in ids}
  if more<=ids:break
  ids |= more
 result=[]
 for pid in ids:
  try:
   p=Path('/proc',str(pid));r=dict(pid=pid,startticks=rows[pid][1],argv=p.joinpath('cmdline').read_bytes().decode().split('\0'),cwd=os.readlink(p/'cwd'),executable=os.readlink(p/'exe'))
   result.append(r);seen[str(pid)+'/'+r['startticks']]=r
  except OSError:pass
 (O/'processes.json').write_text(json.dumps(seen,indent=2));return result

def request(name,path,body=None):
 req=urllib.request.Request(base+path,data=None if body is None else json.dumps(body).encode(),headers={'X-JustSearch-Session':token,'Content-Type':'application/json'})
 try:r=urllib.request.urlopen(req,timeout=30)
 except urllib.error.HTTPError as e:r=e
 raw=r.read();x=json.loads(raw);(O/(name+'.json')).write_text(json.dumps(dict(path=path,status=r.status,request=body,body=x),indent=2));return r.status,x
try:
 script=R/'modules/ui/build/install/ui/bin/ui';install={str(p.relative_to(script.parent.parent)):hashlib.sha256(p.read_bytes()).hexdigest() for p in script.parent.parent.rglob('*') if p.is_file()};(O/'install-hashes.json').write_text(json.dumps(install,indent=2))
 engine=subprocess.Popen([str(script)],cwd=P,env=env,stdout=(O/'engine.log').open('w'),stderr=subprocess.STDOUT,start_new_session=True)
 manifest=P/'data/runtime/manifest.json';m=None
 for _ in range(180):
  cohort()
  if engine.poll() is not None:raise RuntimeError('Engine exited; see log')
  try:
   m=json.loads(manifest.read_text())
   if m.get('head',{}).get('apiPort') and m.get('worker',{}).get('state')=='ready':break
  except (OSError,ValueError):pass
  time.sleep(.5)
 else:raise RuntimeError('Engine readiness timeout; no retry')
 base='http://127.0.0.1:'+str(m['head']['apiPort']);token=m['head'].get('sessionToken','');redacted=json.loads(json.dumps(m));redacted['head']['sessionToken']='[redacted]';(O/'manifest.json').write_text(json.dumps(redacted,indent=2))
 for name,path in [('health','/api/health'),('status','/api/status'),('settings','/api/settings/v2'),('catalog','/api/registry/surfaces')]:request(name,path)
 st,x=request('add-root','/api/indexing/roots',{'path':str(P/'corpus'),'collection':'flip-verifier'})
 if st!=200:raise RuntimeError('Private corpus admission refused')
 s=socket.socket();s.bind(('127.0.0.1',0));port=s.getsockname()[1];s.close()
 ve={k:v for k,v in env.items() if not k.startswith('JUSTSEARCH_')};ve['VITE_API_PORT']=str(m['head']['apiPort'])
 vite=subprocess.Popen(['node','node_modules/vite/bin/vite.js','--host','127.0.0.1','--port',str(port),'--strictPort'],cwd=R/'modules/ui-web',env=ve,stdout=(O/'vite.log').open('w'),stderr=subprocess.STDOUT,start_new_session=True)
 for _ in range(60):
  if vite.poll() is not None:raise RuntimeError('Private Vite exited')
  try:urllib.request.urlopen('http://127.0.0.1:'+str(port),timeout=1);break
  except OSError:time.sleep(.5)
 else:raise RuntimeError('Private Vite startup timeout')
 info=dict(label=label,head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=R,text=True).strip(),tree=str(R),port=port,enginePort=m['head']['apiPort'],profile=str(P),corpus=str(P/'corpus'),chosen=str(P/'corpus/chosen-alpha.txt'),decoy=str(P/'corpus/unchosen-decoy.txt'),scope='Own native Engine, actual registry/status/store/index; model disabled; in_process extraction fixture')
 (O/'ready.json').write_text(json.dumps(info,indent=2));print('READY',label,port,flush=True)
 end=time.monotonic()+18000
 while not (O/'STOP').exists() and time.monotonic()<end:
  cohort()
  if engine.poll() is not None or vite.poll() is not None:raise RuntimeError('Own service exited')
  for j in sorted(jobs.glob('*.json')):
   if j.with_suffix('.done').exists():continue
   job=json.loads(j.read_text());name=j.stem;cmd=job['command'];ce={k:v for k,v in os.environ.items() if not k.startswith('JUSTSEARCH_') and k not in ['JAVA_OPTS','JAVA_TOOL_OPTIONS','_JAVA_OPTIONS','JDK_JAVA_OPTIONS','UI_OPTS','DISPLAY','WAYLAND_DISPLAY']};ce.update(CUDA_VISIBLE_DEVICES='-1',RUNTIME_INFO=str(O/'ready.json'),RUNTIME_OUT=str(O),RUNTIME_TOKEN=token)
   with (O/(name+'.log')).open('w') as f:
    child=subprocess.Popen(cmd,cwd=R,env=ce,stdout=f,stderr=subprocess.STDOUT,start_new_session=True)
    while child.poll() is None:
     cohort()
     if (O/'STOP').exists():os.killpg(child.pid,signal.SIGTERM)
     time.sleep(.5)
   j.with_suffix('.done').write_text(json.dumps(dict(command=cmd,exit=child.returncode)));print(name,child.returncode,flush=True);child=None
  time.sleep(.5)
finally:
 rows=cohort()
 for p in [child,vite,engine]:
  if p and p.poll() is None:
   os.killpg(p.pid,signal.SIGTERM)
   try:p.wait(15)
   except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);p.wait()
 for r in rows:
  try:
   p=Path('/proc',str(r['pid']))
   if p.joinpath('stat').read_text().split()[21]==r['startticks']:os.kill(r['pid'],signal.SIGTERM)
  except (OSError,ProcessLookupError):pass
 shutil.rmtree(P)
 (O/'cleanup.json').write_text(json.dumps(dict(profileRemoved=not P.exists(),engineExit=engine.returncode if engine else None,viteExit=vite.returncode if vite else None,ownedProcessIds=rows),indent=2))

