import json,os,subprocess,time,sys
from pathlib import Path
P=Path(__file__).parent
pairs=[('before',str(P.parent/'before')),('candidate','/home/elias/dev/js-uiux-compat-ingress')]
for label,tree in pairs:
 log=P/('gradle-'+label+'.log');end=time.monotonic()+10800
 while True:
  text=log.read_text() if log.exists() else ''
  if 'BUILD SUCCESSFUL' in text:break
  if 'BUILD FAILED' in text or 'gradle-slot: no slot' in text:raise RuntimeError('Build unavailable: '+label+'; inspect build result before launching')
  if time.monotonic()>end:raise RuntimeError('Build wait deadline: '+label)
  time.sleep(5)
 O=P/('runtime-'+label);(O/'jobs').mkdir(parents=True,exist_ok=True)
 runtime=None
 try:
  with (P/('runtime-'+label+'-launch.log')).open('w') as f:
   runtime=subprocess.Popen([sys.executable,str(P/'runtime.py'),label,tree],stdout=f,stderr=subprocess.STDOUT)
   deadline=time.monotonic()+180
   while not (O/'ready.json').exists():
    if runtime.poll() is not None:raise RuntimeError('Own runtime failed to start: '+label)
    if time.monotonic()>deadline:raise RuntimeError('Own runtime readiness deadline: '+label)
    time.sleep(.5)
   print('Ready for browser:',label,flush=True)
   for index,script in enumerate(['cold-case.mjs','cold-refusal.mjs'],1):
    job=O/'jobs'/('0'+str(index)+'-'+script.replace('.mjs','')+'.json')
    job.write_text(json.dumps({'command':['node',str(P/script)]}))
    deadline=time.monotonic()+180
    while not job.with_suffix('.done').exists():
     if runtime.poll() is not None:raise RuntimeError('Own runtime exited: '+label)
     if time.monotonic()>deadline:raise RuntimeError('Browser check deadline: '+label+'/'+script)
     time.sleep(.5)
    result=json.loads(job.with_suffix('.done').read_text());print(label,script,'exit',result['exit'],flush=True)
    if label=='candidate' and result['exit']!=0:raise RuntimeError('Candidate browser check failed; no retry: '+script)
 finally:
  if runtime and runtime.poll() is None:
   (O/'STOP').write_text('Done with own paired browser checks. Stop only owned processes.\n')
   try:runtime.wait(45)
   except subprocess.TimeoutExpired:runtime.terminate();runtime.wait(20)
  if not (O/'cleanup.json').exists():raise RuntimeError('Runtime cleanup missing: '+label)
  cleanup=json.loads((O/'cleanup.json').read_text());assert cleanup['profileRemoved']
 print('Private runtime cleaned:',label,flush=True)
print('Paired checks complete',flush=True)
